import {button,esc,phraseText,quotedText} from './ui.js';
import {videoLesson,videoProgress} from './video-lesson-state.js';
import {videoContent} from './video-lesson-content.js';
export function renderVideoDetective(s,top,frame){
 const l=videoLesson(s),p=videoProgress(s),x=videoContent[l.id][0],d=x.detective,jp=l.direction==='ja-ko',ui=jp?'ja':'ko',lang=jp?'ko':'ja',label=(ko,ja)=>jp?ja:ko;
 const stages=['watch','infer','clue','learn'],step=stages.indexOf(p.phase),text=(v,parts)=>jp?esc(v):phraseText(v,parts),question=p.phase==='infer'?d.intent:d.clue;
 const quote=`<section class="video-dialogue"><blockquote lang="${lang}">${text(x.quote,x.parts)}</blockquote><details><summary>${label('번역 보기','訳を見る')}</summary><p lang="${ui}">${quotedText(x.translation)}</p></details></section>`;
 const support=`<details class="video-support"><summary>${label('출처·재생 안내','出典・再生について')}</summary><p class="video-source">${esc(x.work)} · ${esc(x.channel)}</p><p class="video-help">${label('재생 버튼을 눌러 장면을 살펴보세요. 인터넷 연결이 필요해요.','再生ボタンを押して場面を見ましょう。インターネット接続が必要です。')}</p><a class="video-original" href="https://www.youtube.com/watch?v=${x.videoId}&t=${x.startSeconds}s" target="_blank" rel="noopener noreferrer">${label('공식 유튜브에서 보기','公式YouTubeで見る')}</a></details>`;
 const nav=()=>`<div class="button-pair">${button(label('이전','戻る'),'video-previous','secondary',p.phase==='watch'?'disabled':'')}${['infer','clue'].includes(p.phase)&&!p.checked?button(label('확인','確認'),'video-check','primary',p.selected===null?'disabled':''):button(p.phase==='learn'?label('학습 완료','学習完了'):p.phase==='watch'?{clue:label('단서로 돌아가기','手がかりに戻る'),learn:label('해설로 돌아가기','解説に戻る')}[p.resume]??label('속뜻 추리하기','気持ちを推理する'):p.phase==='infer'?label('단서 찾기','手がかりを探す'):label('해설 보기','解説を見る'),'video-next')}</div>`;
 let body;
 if(p.phase==='watch')body=`<h1>${quotedText(d.title)}</h1><p>${quotedText(d.context)}</p><p class="video-detective-prompt">${quotedText(d.mission)}</p>${frame(x)}<details class="video-transcript"><summary>${label('대사 확인','セリフを確認')}</summary>${quote}</details>${support}${nav()}`;
 else if(['infer','clue'].includes(p.phase))body=`<h1>${quotedText(question.prompt)}</h1>${quote}<p class="video-detective-context">${quotedText(d.context)}</p><div class="video-detective-choices">${question.options.map((o,i)=>button(quotedText(o),'video-select',`secondary${p.selected===i?' selected':''}${p.checked&&p.selected===i?' correct':''}`,`data-id="${i}" aria-pressed="${p.selected===i}" ${p.checked?'disabled':''}`)).join('')}</div>${p.checked||p.retry?`<div class="lesson-verdict video-detective-feedback${p.checked?' success':''}" role="status"><p class="video-detective-verdict">${p.checked?label('정답이에요','正解です'):label('다시 생각해 봐요','もう一度考えましょう')}</p><p>${quotedText(p.checked?question.success:question.hints[p.selected])}</p></div>`:''}${button(label('장면 다시 보기','場面をもう一度'),'video-replay','text-button')}${nav()}`;
 else if(p.phase==='learn')body=`<h1>${label('찾아낸 속뜻','読み取れた気持ち')}</h1><section class="video-detective-result"><p class="video-label">${label('겉으로 한 말','言葉の表面上の意味')}</p><p>${quotedText(d.literal)}</p><p class="video-label">${label('이 장면에서의 뜻','この場面での意味')}</p><h2>${quotedText(d.meaning)}</h2></section><p>${quotedText(d.explanation)}</p><section class="video-example"><h2>${label('다른 상황이라면?','別の場面なら？')}</h2><p>${quotedText(d.contrast)}</p></section>${button(label('장면 다시 보기','場面をもう一度'),'video-replay','text-button')}${nav()}`;
 return `${top(`${l.number}. ${l.title}`)}<div class="lesson-progress" role="progressbar" aria-label="${label('학습 진행률','学習の進み具合')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${step*25}"><span style="width:${step*25}%"></span></div><main class="page video-lesson video-detective video-phase-${p.phase}" lang="${ui}">${body||''}</main>`;
}
